// features: Upload vendor documents: "Documents cannot be added to a vendor under review"
// The scenario's Then-steps expect 409 vendor_locked, so the test asserts that. The
// platform note asking to remove ensure_editable() from the backend conflicts with that
// expectation, so this file does not depend on any backend change.
import { expect, expectStatus, test } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("uploading a document to a vendor in review is rejected with vendor_locked", { tag: "@DOC-06" }, async ({ apiAs }) => {
    // Arrange: a unique draft vendor owned by the signed-in member, submitted into review.
    const member = await apiAs("member");
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

    const created = await member.post("/api/vendors", {
      data: {
        name: `DOC06 Vendor ${suffix}`,
        category: "services",
        contact_email: `ops-${suffix}@example.test`,
      },
    });
    const vendor = await expectStatus<{ id: string; status: string }>(created, 201);
    expect(vendor.status).toBe("draft");

    const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
    const underReview = await expectStatus<{ id: string; status: string }>(submitted, 200);
    expect(underReview.status).toBe("in_review");

    // Act: attempt to upload a W-9 to the vendor under review.
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9.txt",
          mimeType: "text/plain",
          buffer: Buffer.from(`W-9 for ${suffix}\n`),
        },
      },
    });

    // Assert: rejected with the locked-vendor error code.
    const body = await expectStatus<{ error: { code: string } }>(upload, 409);
    expect(body.error.code).toBe("vendor_locked");
  });
});
